import json
from pathlib import Path

CACHE_DIR = Path('cache/Qwen_Qwen2.5_0.5B/ioi')
METHODS = ['eap_ig', 'edge_pruning', 'ifr']

raw = {}
for m in METHODS:
    with open(CACHE_DIR / f'cache_{m}.json') as f:
        raw[m] = json.load(f)

def topn(scores, n):
    s = sorted(scores.items(), key=lambda x: abs(x[1]), reverse=True)
    return {e for e, _ in s[:n]}

def jaccard(a, b):
    if not a and not b: return 0.0
    return len(a & b) / len(a | b) if (a | b) else 0.0

def css_dist(circuits):
    all_sel = set()
    for c in circuits.values(): all_sel |= c
    d = {'1/3':0, '2/3':0, '3/3':0}
    for e in all_sel:
        cnt = sum(1 for c in circuits.values() if e in c)
        d[f'{cnt}/3'] += 1
    return d

# Build full results dict
results = {
    'experiment': 'proportional_binarization_ablation',
    'model': 'Qwen/Qwen2.5-0.5B',
    'task': 'ioi',
    'total_edges': {m: len(raw[m]) for m in METHODS},
    'percentages': {}
}

for pct in [0.056, 0.1, 0.3, 0.5, 1.0, 2.0, 3.5]:
    c = {}
    ns = {}
    for m in METHODS:
        n = max(1, round(len(raw[m]) * pct / 100))
        ns[m] = n
        c[m] = topn(raw[m], n)
    d = css_dist(c)
    pairs = [('eap_ig','edge_pruning'),('eap_ig','ifr'),('edge_pruning','ifr')]
    j = {}
    overlaps = {}
    for a,b in pairs:
        j[f'{a}_vs_{b}'] = round(jaccard(c[a], c[b]), 4)
        overlaps[f'{a}_vs_{b}'] = len(c[a] & c[b])
    core = len(c['eap_ig'] & c['edge_pruning'] & c['ifr'])
    results['percentages'][str(pct)] = {
        'N': ns, 'css': d, 'jaccard': j, 'overlap_counts': overlaps, 'core_3way': core
    }

# Fixed N=100 baseline
c100 = {m: topn(raw[m], 100) for m in METHODS}
d100 = css_dist(c100)
j100 = {}
for a,b in [('eap_ig','edge_pruning'),('eap_ig','ifr'),('edge_pruning','ifr')]:
    j100[f'{a}_vs_{b}'] = round(jaccard(c100[a], c100[b]), 4)
results['fixed_n100'] = {'css': d100, 'jaccard': j100}

# Layer distribution of top-0.3% per method
for m in METHODS:
    s = sorted(raw[m].items(), key=lambda x: abs(x[1]), reverse=True)
    n = max(1, round(len(raw[m]) * 0.3 / 100))
    top_edges = [e for e, _ in s[:n]]
    # extract source layer
    layers = {}
    for e in top_edges:
        src = e.split('->')[0]
        if src == 'input':
            l = -1
        elif src.startswith('a'):
            l = int(src.split('.')[0][1:])
        elif src.startswith('m'):
            l = int(src[1:])
        else:
            l = -2
        layers[l] = layers.get(l, 0) + 1
    results.setdefault('layer_distribution_03pct', {})[m] = dict(sorted(layers.items()))

out = Path('results/Qwen_Qwen2.5_0.5B_ioi/proportional_binarize_ablation.json')
out.parent.mkdir(parents=True, exist_ok=True)
with open(out, 'w') as f:
    json.dump(results, f, indent=2)
print(f'Saved to {out}')
print(json.dumps(results, indent=2))
"
